ALTER POLICY private_lead_boundary ON public.leads USING(private_owner_id IS NULL OR (private_owner_id=auth.uid() AND public.lead_workspace_active()) OR (public.routing_admin() AND ((intake_source='manual' AND created_by IS DISTINCT FROM private_owner_id) OR EXISTS(SELECT 1 FROM public.lead_assignment_events e WHERE e.lead_id=leads.id AND e.assignment_type='automatic')))) WITH CHECK(private_owner_id IS NULL OR (private_owner_id=auth.uid() AND public.lead_workspace_active()) OR (public.routing_admin() AND ((intake_source='manual' AND created_by IS DISTINCT FROM private_owner_id) OR EXISTS(SELECT 1 FROM public.lead_assignment_events e WHERE e.lead_id=leads.id AND e.assignment_type='automatic'))));